<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Factorial Visualizer & Calculator</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800&family=JetBrains+Mono:wght@400;700&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #0f172a;
            background-image: 
                radial-gradient(at 0% 0%, hsla(253,16%,7%,1) 0, transparent 50%), 
                radial-gradient(at 50% 0%, hsla(225,39%,30%,1) 0, transparent 50%), 
                radial-gradient(at 100% 0%, hsla(339,49%,30%,1) 0, transparent 50%);
            background-attachment: fixed;
            color: #e2e8f0;
        }
        .math-font {
            font-family: 'JetBrains Mono', monospace;
        }
        .glass-panel {
            background: rgba(30, 41, 59, 0.7);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.1);
        }
        .step-card {
            transition: all 0.3s ease;
        }
        .step-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3);
            border-color: #818cf8;
        }
        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #1e293b; 
        }
        ::-webkit-scrollbar-thumb {
            background: #475569; 
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #64748b; 
        }
        .glow-text {
            text-shadow: 0 0 10px rgba(129, 140, 248, 0.5);
        }
        @keyframes slideIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-slide-in {
            animation: slideIn 0.4s ease-out forwards;
        }
    </style>
</head>
<body class="min-h-screen flex flex-col">

    <!-- Navigation / Header -->
    <nav class="w-full glass-panel sticky top-0 z-50 border-b border-slate-700">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div class="flex items-center justify-between h-16">
                <div class="flex items-center gap-3">
                    <div class="w-8 h-8 bg-indigo-500 rounded-lg flex items-center justify-center text-white font-bold text-lg shadow-lg shadow-indigo-500/50">!</div>
                    <span class="text-xl font-bold tracking-tight text-white">Fact<span class="text-indigo-400">Viz</span></span>
                </div>
                <div class="hidden md:block">
                    <div class="ml-10 flex items-baseline space-x-4">
                        <a href="#" class="text-white px-3 py-2 rounded-md text-sm font-medium bg-slate-800 border border-slate-600">Calculator</a>
                        <a href="#info" class="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium">About Factorials</a>
                    </div>
                </div>
            </div>
        </div>
    </nav>

    <!-- Main Content -->
    <main class="flex-grow container mx-auto px-4 py-8 gap-8 grid grid-cols-1 lg:grid-cols-12">

        <!-- Left Column: Controls -->
        <div class="lg:col-span-4 space-y-6">
            <!-- Input Card -->
            <div class="glass-panel rounded-2xl p-6 shadow-xl">
                <h2 class="text-2xl font-bold text-white mb-2">Input</h2>
                <p class="text-slate-400 text-sm mb-6">Enter a number to calculate its factorial (n!).</p>

                <div class="space-y-4">
                    <div>
                        <label for="numberInput" class="block text-sm font-medium text-slate-300 mb-1">Number (n)</label>
                        <div class="relative">
                            <input type="number" id="numberInput" min="0" max="100000" value="5" 
                                class="block w-full bg-slate-800 border border-slate-600 rounded-xl py-3 px-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all text-lg font-mono"
                                placeholder="e.g. 5">
                            <div class="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                                <span class="text-slate-500 font-mono">!</span>
                            </div>
                        </div>
                        <p id="inputError" class="text-red-400 text-xs mt-1 hidden">Please enter a valid number (0-100,000).</p>
                    </div>

                    <!-- Slider for quick selection -->
                    <div>
                        <label for="sliderInput" class="block text-sm font-medium text-slate-300 mb-1">Quick Select</label>
                        <input type="range" id="sliderInput" min="0" max="100" value="5" class="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500">
                        <div class="flex justify-between text-xs text-slate-500 mt-1">
                            <span>0</span>
                            <span>50</span>
                            <span>100</span>
                        </div>
                    </div>

                    <button id="calculateBtn" class="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-xl transition duration-200 shadow-lg shadow-indigo-600/30 flex items-center justify-center gap-2 group">
                        <span>Calculate</span>
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                    </button>
                </div>
            </div>

            <!-- Stats Card -->
            <div class="glass-panel rounded-2xl p-6 shadow-xl">
                <h3 class="text-lg font-semibold text-white mb-4 border-b border-slate-700 pb-2">Statistics</h3>
                <div class="space-y-4">
                    <div class="flex justify-between items-center">
                        <span class="text-slate-400 text-sm">Time Complexity</span>
                        <span class="text-indigo-300 font-mono text-xs bg-indigo-900/50 px-2 py-1 rounded">O(n)</span>
                    </div>
                    <div class="flex justify-between items-center">
                        <span class="text-slate-400 text-sm">Result Digits</span>
                        <span id="digitCount" class="text-white font-mono font-bold">-</span>
                    </div>
                    <div class="flex justify-between items-center">
                        <span class="text-slate-400 text-sm">Trailing Zeros</span>
                        <span id="trailingZeros" class="text-emerald-400 font-mono font-bold">-</span>
                    </div>
                </div>
            </div>

            <!-- History -->
            <div class="glass-panel rounded-2xl p-6 shadow-xl flex-grow">
                <h3 class="text-lg font-semibold text-white mb-4 flex items-center justify-between">
                    <span>Recent History</span>
                    <button id="clearHistory" class="text-xs text-slate-500 hover:text-white transition-colors">Clear</button>
                </h3>
                <ul id="historyList" class="space-y-2 max-h-60 overflow-y-auto pr-2">
                    <!-- History items injected here -->
                    <li class="text-slate-500 text-sm text-center italic py-4">No calculations yet</li>
                </ul>
            </div>
        </div>

        <!-- Right Column: Visualization & Results -->
        <div class="lg:col-span-8 space-y-6">

            <!-- Visualization Section -->
            <div class="glass-panel rounded-2xl p-1 shadow-xl overflow-hidden relative min-h-[300px] flex flex-col">
                <div class="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>

                <div class="p-6 pb-2 flex justify-between items-end">
                    <div>
                        <h2 class="text-2xl font-bold text-white">Visualization</h2>
                        <p class="text-slate-400 text-sm mt-1">Step-by-step multiplication process</p>
                    </div>
                    <div id="vizStatus" class="text-xs font-mono text-indigo-300 bg-indigo-900/30 px-2 py-1 rounded border border-indigo-500/30 hidden">
                        Rendering...
                    </div>
                </div>

                <!-- Scrollable Visualization Container -->
                <div id="visualizationContainer" class="flex-grow overflow-x-auto overflow-y-hidden p-6 flex items-center gap-4 scroll-smooth">
                    <!-- Steps injected here -->
                    <div class="flex items-center justify-center w-full h-full text-slate-500">
                        Enter a number to visualize the logic.
                    </div>
                </div>
            </div>

            <!-- Result Output -->
            <div class="glass-panel rounded-2xl p-6 shadow-xl border-l-4 border-indigo-500">
                <div class="flex justify-between items-start mb-2">
                    <h3 class="text-lg font-semibold text-white">Result</h3>
                    <button id="copyBtn" class="text-xs flex items-center gap-1 text-slate-400 hover:text-white transition-colors" disabled>
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                        </svg>
                        Copy
                    </button>
                </div>
                <div class="bg-slate-900/80 rounded-xl p-4 overflow-hidden">
                    <div id="resultOutput" class="math-font text-2xl md:text-4xl text-emerald-400 break-all leading-tight opacity-50">
                        Waiting for input...
                    </div>
                </div>
                <div id="scientificNotation" class="mt-2 text-right text-sm text-slate-500 font-mono hidden">
                    Approx: <span class="text-slate-300"></span>
                </div>
            </div>

            <!-- Code Snippet Section -->
            <div class="glass-panel rounded-2xl p-6 shadow-xl">
                 <h3 class="text-lg font-semibold text-white mb-4">Implementation Logic</h3>
                 <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                     <div class="bg-slate-950 rounded-lg p-4 border border-slate-800 relative group">
                         <div class="absolute top-2 right-2 text-[10px] text-slate-500 font-bold uppercase tracking-wider">Iterative</div>
                         <pre class="text-xs sm:text-sm text-slate-300 font-mono overflow-x-auto"><code>function factorial(n) {
  let result = 1n;
  for (let i = 1n; i <= n; i++) {
    result *= i;
  }
  return result;
}</code></pre>
                     </div>
                     <div class="bg-slate-950 rounded-lg p-4 border border-slate-800 relative group">
                         <div class="absolute top-2 right-2 text-[10px] text-slate-500 font-bold uppercase tracking-wider">Recursive</div>
                         <pre class="text-xs sm:text-sm text-slate-300 font-mono overflow-x-auto"><code>function factorial(n) {
  if (n === 0n || n === 1n) {
    return 1n;
  }
  return n * factorial(n - 1n);
}</code></pre>
                     </div>
                 </div>
            </div>

        </div>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const numberInput = document.getElementById('numberInput');
