    <style>
        body {
            font-family: 'Poppins', sans-serif;
            background: linear-gradient(135deg, #fdfbfb 0%, #ebedee 100%);
        }

        /* Smoothie Liquid Animation */
        @keyframes wave {
            0% { transform: translateX(0) translateZ(0) scaleY(1); }
            50% { transform: translateX(-25%) translateZ(0) scaleY(0.55); }
            100% { transform: translateX(-50%) translateZ(0) scaleY(1); }
        }

        @keyframes blend-pulse {
            0% { transform: scale(1); opacity: 0.8; }
            50% { transform: scale(1.05); opacity: 1; }
            100% { transform: scale(1); opacity: 0.8; }
        }

        @keyframes spin-blade {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(3600deg); }
        }

        .liquid-wave {
            background: url('data:image/svg+xml;utf8,%3Csvg viewBox="0 0 1200 120" xmlns="http://www.w3.org/2000/svg"%3E%3Cpath d="M321.39 56.44c58-10.79 114.16-30.13 172-41.86 82.39-16.72 168.19-17.73 250.45-.39C823.78 31 906.67 72 985.66 92.83c70.05 18.48 146.53 26.09 214.34 3V0H0v27.35a600.21 600.21 0 00321.39 29.09z" fill="%23ffffff" fill-opacity="0.4"/%3E%3C/svg%3E');
            background-size: 200% 100%;
            animation: wave 10s linear infinite;
            width: 200%;
            height: 20px;
            position: absolute;
            top: -10px;
            left: 0;
        }

        .blender-jar {
            transition: all 0.3s ease;
        }

        .ingredient-btn {
            transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }
        .ingredient-btn:active {
            transform: scale(0.9);
        }
        .ingredient-btn.selected {
            border-color: #10B981;
            background-color: #ECFDF5;
            transform: translateY(-2px);
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #f1f1f1; 
        }
        ::-webkit-scrollbar-thumb {
            background: #cbd5e1; 
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #94a3b8; 
        }

        .bladde-spin {
            animation: spin-blade 2s linear infinite;
        }

        .vibrate {
            animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both infinite;
        }

        @keyframes shake {
            10%, 90% { transform: translate3d(-1px, 0, 0); }
            20%, 80% { transform: translate3d(2px, 0, 0); }
            30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
            40%, 60% { transform: translate3d(4px, 0, 0); }
        }
    </style>
</head>
