<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Wasteland Echoes - Terminal</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=VT323&display=swap" rel="stylesheet">
    <style>
        :root {
            --crt-green: #33ff00;
            --crt-bg: #0a0a0a;
            --crt-dim: #1a2a1a;
        }

        body {
            background-color: #050505;
            font-family: 'VT323', monospace;
            color: var(--crt-green);
            overflow: hidden;
            margin: 0;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* CRT Effects */
        .crt-container {
            position: relative;
            width: 100%;
            max-width: 1000px;
            height: 95vh;
            background: #000;
            border: 2px solid #333;
            box-shadow: 0 0 20px rgba(51, 255, 0, 0.2);
            border-radius: 10px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }

        .scanlines {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(
                to bottom,
                rgba(255,255,255,0),
                rgba(255,255,255,0) 50%,
                rgba(0,0,0,0.2) 50%,
                rgba(0,0,0,0.2)
            );
            background-size: 100% 4px;
            pointer-events: none;
            z-index: 50;
            opacity: 0.6;
        }

        .glow-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle, rgba(51, 255, 0, 0.05) 0%, rgba(0,0,0,0.8) 90%);
            pointer-events: none;
            z-index: 51;
            box-shadow: inset 0 0 80px rgba(0,0,0,0.9);
        }

        .flicker {
            animation: flicker 0.15s infinite;
        }

        @keyframes flicker {
            0% { opacity: 0.97; }
            50% { opacity: 1; }
            100% { opacity: 0.98; }
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #0a0a0a; 
        }
        ::-webkit-scrollbar-thumb {
            background: #33ff00; 
        }

        /* Utilities */
        .text-shadow {
            text-shadow: 0 0 5px rgba(51, 255, 0, 0.7);
        }

        .border-neon {
            border: 1px solid rgba(51, 255, 0, 0.3);
            box-shadow: 0 0 5px rgba(51, 255, 0, 0.1);
        }

        .btn-retro {
            background: transparent;
            border: 1px solid var(--crt-green);
            color: var(--crt-green);
            padding: 8px 16px;
            font-family: 'VT323', monospace;
            font-size: 1.2rem;
            cursor: pointer;
            transition: all 0.2s;
            text-transform: uppercase;
        }

        .btn-retro:hover:not(:disabled) {
            background: var(--crt-green);
            color: #000;
            box-shadow: 0 0 15px var(--crt-green);
        }

        .btn-retro:disabled {
            border-color: #333;
            color: #555;
            cursor: not-allowed;
        }

        .stat-bar-bg {
            background: #111;
            border: 1px solid #333;
            height: 20px;
            width: 100%;
            position: relative;
        }

        .stat-bar-fill {
            height: 100%;
            transition: width 0.5s ease, background-color 0.5s ease;
        }

        .typing-cursor::after {
            content: '█';
            animation: blink 1s infinite;
        }

        @keyframes blink {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
        }

        /* ASCII Art Placeholder */
        pre {
            line-height: 1.1;
            font-size: 10px;
        }

        /* Modal */
        .modal-bg {
            background: rgba(0, 0, 0, 0.85);
            backdrop-filter: blur(4px);
        }
    </style>
</head>
